use super::{svg_from_body, Arc, Image, SlackShellIcon};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use gpui::ImageFormat;

pub(super) fn slack_illustration_image(icon: SlackShellIcon) -> Option<Arc<Image>> {
    match icon {
        SlackShellIcon::Slackbot => Some(Arc::new(Image::from_bytes(
            ImageFormat::Png,
            STANDARD
                .decode(SLACKBOT_HEART_FRAME_BASE64)
                .expect("embedded Slackbot heart frame must be valid base64"),
        ))),
        SlackShellIcon::EmptyDrafts => Some(svg_from_body("0 0 168 160", EMPTY_DRAFTS_BODY.into())),
        SlackShellIcon::EmptyScheduled => {
            Some(svg_from_body("0 0 168 162", EMPTY_SCHEDULED_BODY.into()))
        }
        _ => None,
    }
}

